<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/mou.php';
$user=require_role('admin','staf_bkk');mou_require_ready();
$partnerId=positive_id($_GET['mitra_id']??'');if(isset($_GET['mitra_id'])&&$_GET['mitra_id']!==''&&!$partnerId){panel_not_found();}
$partner=null;if($partnerId){try{$partner=partner_find($partnerId);}catch(InvalidArgumentException){panel_not_found();}}
$q=input_text($_GET,'q');$status=input_text($_GET,'status');
if(!valid_text($q,100,false)||!in_array($status,['','belum','aktif','kedaluwarsa'],true)){http_response_code(400);exit('Filter MoU tidak valid.');}
$asOf=new DateTimeImmutable('now',new DateTimeZone('Asia/Jakarta'));$today=mou_today($asOf);$where='1=1';$params=[];
if($partnerId){$where.=' AND d.mitra_id=:partner';$params['partner']=$partnerId;}
if($q!==''){$pattern='%'.str_replace(['!','%','_'],['!!','!%','!_'],$q).'%';$where.=" AND (d.nomor_dokumen LIKE :nomor ESCAPE '!' OR m.nama LIKE :nama ESCAPE '!')";$params+=['nomor'=>$pattern,'nama'=>$pattern];}
if($status==='belum'){$where.=' AND d.tanggal_mulai>:today';$params['today']=$today;}
elseif($status==='kedaluwarsa'){$where.=' AND d.tanggal_berakhir<:today';$params['today']=$today;}
elseif($status==='aktif'){$where.=' AND d.tanggal_mulai<=:start_day AND d.tanggal_berakhir>=:end_day';$params+=['start_day'=>$today,'end_day'=>$today];}
$from=' FROM mitra_mous d JOIN mitra m ON m.id=d.mitra_id WHERE '.$where;
$total=(int)panel_query('SELECT COUNT(*)'.$from,$params)->fetchColumn();$pages=max(1,(int)ceil($total/20));$page=min($pages,positive_id($_GET['page']??'1')??1);
$rows=panel_query('SELECT d.*,m.nama'.$from.' ORDER BY d.tanggal_berakhir DESC,d.id DESC LIMIT :limit OFFSET :offset',$params+['limit'=>20,'offset'=>($page-1)*20])->fetchAll();
$filters=['mitra_id'=>$partnerId?(string)$partnerId:'','q'=>$q,'status'=>$status];
panel_start($user,'Riwayat MoU','mou');
?>
<div class="mou-list-page">
<header class="partner-detail-heading"><div><h1><?= panel_icon('certificate') ?> Riwayat MoU<?= $partner?': '.e($partner['nama']):'' ?></h1><p>Kelola dokumen kerja sama dan riwayat perpanjangan.</p></div><nav aria-label="Pengelolaan MoU"><a class="mou-add" href="<?= e(base_url('panel/mou/form.php'.($partnerId?'?mitra_id='.$partnerId:''))) ?>"><?= panel_icon('add') ?> Tambah MoU</a><a href="<?= e(base_url('panel/mitra/')) ?>"><?= panel_icon('mitra') ?> Data mitra</a><?php if($partnerId): ?><a class="detail-edit" href="<?= e(base_url('panel/mitra/detail.php?id='.$partnerId)) ?>"><?= panel_icon('akun') ?> Profil / PIC</a><a href="<?= e(base_url('panel/mou/')) ?>"><?= panel_icon('berita') ?> Semua MoU</a><?php endif; ?></nav></header>
<form class="filter-form card" method="get"><?php if($partnerId): ?><input type="hidden" name="mitra_id" value="<?= $partnerId ?>"><?php endif; ?><label><span><?= panel_icon('search') ?> Cari nomor dokumen / nama mitra</span><input name="q" maxlength="100" value="<?= e($q) ?>"></label><label><span><?= panel_icon('check-circle') ?> Status</span><select name="status"><?php foreach([''=>'Semua','belum'=>'Belum Berlaku','aktif'=>'Aktif','kedaluwarsa'=>'Kedaluwarsa'] as $key=>$label): ?><option value="<?= $key ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button type="submit"><?= panel_icon('search') ?> Cari</button><a href="<?= e(base_url('panel/mou/'.($partnerId?'?mitra_id='.$partnerId:''))) ?>"><?= panel_icon('reset') ?> Reset</a></form>
<div class="mou-table-heading"><h2><?= panel_icon('berita') ?> Daftar dokumen</h2><span><?= $total ?> dokumen &middot; Halaman <?= $page ?> dari <?= $pages ?></span></div>
<div class="table-scroll mou-list-sheet mou-documents-sheet" data-vertical-list tabindex="0" role="region" aria-label="Daftar MoU, gulir untuk melihat dokumen"><table><thead><tr><th><span class="mou-column-label"><?= panel_icon('mitra') ?> Mitra</span></th><th><span class="mou-column-label"><?= panel_icon('berita') ?> Nomor dokumen</span></th><th><span class="mou-column-label"><?= panel_icon('calendar') ?> Mulai</span></th><th><span class="mou-column-label"><?= panel_icon('calendar') ?> Berakhir</span></th><th><span class="mou-column-label"><?= panel_icon('check-circle') ?> Status</span></th><th><span class="mou-column-label"><?= panel_icon('history') ?> Riwayat</span></th><th><span class="mou-column-label"><?= panel_icon('download') ?> Berkas</span></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a href="<?= e(base_url('panel/mou/?mitra_id='.$row['mitra_id'])) ?>"><?= e($row['nama']) ?></a></td><td><?= e($row['nomor_dokumen']) ?></td><td><?= e($row['tanggal_mulai']) ?></td><td><?= e($row['tanggal_berakhir']) ?></td><td><span class="mou-status <?= $row['tanggal_mulai']>$today?'is-upcoming':($row['tanggal_berakhir']<$today?'is-expired':'is-active') ?>"><?= e(mou_status($row['tanggal_mulai'],$row['tanggal_berakhir'],$asOf)) ?></span></td><td><div class="mou-history-cell"><span class="mou-record-label">Catatan #<?= (int)$row['id'] ?></span><?php if($row['previous_id']): ?><a href="<?= e(base_url('panel/mou/unduh.php?id='.$row['previous_id'])) ?>">MoU sebelumnya #<?= (int)$row['previous_id'] ?></a><?php endif; ?><a href="<?= e(base_url('panel/mou/form.php?mitra_id='.$row['mitra_id'].'&previous_id='.$row['id'])) ?>" class="mou-renew"><?= panel_icon('add') ?> Perpanjang</a></div></td><td><div class="mou-file-cell"><a href="<?= e(base_url('panel/mou/unduh.php?id='.$row['id'])) ?>" class="mou-download"><?= panel_icon('download') ?> Unduh PDF</a><div class="mou-file-meta"><span title="<?= e($row['nama_asli']) ?>"><?= e($row['nama_asli']) ?></span><small><?= number_format($row['ukuran']/1024,1) ?> KB</small></div></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="mou-empty"><?= panel_icon('berita') ?> Belum ada dokumen MoU untuk pilihan ini. Gunakan Tambah MoU untuk mencatat kerja sama.</td></tr><?php endif; ?></tbody></table></div>
<nav class="pagination" aria-label="Halaman MoU"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;} ?><a href="<?= e(base_url('panel/mou/?'.http_build_query($filters+['page'=>$target]))) ?>"><?= $label ?></a><?php endforeach; ?></nav>
</div>
<?php panel_end($user); ?>
